// Reduz a foto antes de subir: economiza dados e deixa o feed leve
// ---- Fotos HEIC (Samsung com "Imagens de alta eficiência", iPhone): o Android e o computador não abrem.
// Converte pra JPG no próprio celular antes de usar. O conversor só é baixado se alguém escolher uma foto HEIC.
async function ehHeic(file) {
    if (!file) return false;
    const t = String(file.type || '').toLowerCase(), n = String(file.name || '').toLowerCase();
    if (/heic|heif/.test(t) || /\.(heic|heif)$/.test(n)) return true;
    if (t && t !== 'application/octet-stream' && t.startsWith('image/') && !/heic|heif/.test(t)) return false;
    try { const cab = new Uint8Array(await file.slice(4, 12).arrayBuffer()); const txt = String.fromCharCode(...cab); return /^ftyp(heic|heix|hevc|heim|heis|mif1|msf1)/.test(txt); } catch (_) { return false; }
}
async function navegadorAbre(file) {
    try { if (window.createImageBitmap) { const b = await createImageBitmap(file); if (b.close) b.close(); return true; } } catch (_) { return false; }
    return new Promise(ok => { const u = URL.createObjectURL(file), im = new Image(); im.onload = () => { URL.revokeObjectURL(u); ok(im.naturalWidth > 0); }; im.onerror = () => { URL.revokeObjectURL(u); ok(false); }; im.src = u; });
}
let heicCarregando = null;
function carregarConversorHeic() {
    if (window.heic2any) return Promise.resolve();
    if (!heicCarregando) heicCarregando = new Promise((ok, erro) => { const sc = document.createElement('script'); sc.src = 'heic2any.min.js?v=1'; sc.onload = ok; sc.onerror = () => { heicCarregando = null; erro(new Error('conversor')); }; document.head.appendChild(sc); });
    return heicCarregando;
}
function avisoPreparandoFoto(on) {
    let el = document.getElementById('avisoFotoPrep');
    if (!on) { if (el) el.remove(); return; }
    if (el) return;
    el = document.createElement('div'); el.id = 'avisoFotoPrep'; el.className = 'aviso-foto-prep';
    el.innerHTML = '<span class="spinner-mini"></span>Preparando a foto…';
    document.body.appendChild(el);
}
async function heicParaJpg(file, silencioso = false) {
    if (!silencioso) avisoPreparandoFoto(true);
    try {
        await carregarConversorHeic();
        let r = await window.heic2any({ blob: file, toType: 'image/jpeg', quality: 0.9 });
        if (Array.isArray(r)) r = r[0];
        if (!r || !r.size) throw new Error('vazio');
        return new File([r], String(file.name || 'foto').replace(/\.(heic|heif)$/i, '') + '.jpg', { type: 'image/jpeg', lastModified: Date.now() });
    } finally { if (!silencioso) avisoPreparandoFoto(false); }
}
// devolve um arquivo que este celular consegue abrir (ou null, com aviso, se não der)
async function fotoLegivel(file) {
    if (!(await ehHeic(file))) return file;
    if (await navegadorAbre(file)) return file; // iPhone abre HEIC: o compressImage já transforma em JPG
    try { return await heicParaJpg(file); }
    catch (_) {
        toast('Não consegui abrir essa foto (formato HEIC). No Samsung: Câmera › Configurações › Formatos › desligue "Imagens de alta eficiência".', 'err');
        return null;
    }
}
// qualquer campo de foto do app: troca a foto HEIC pela versão JPG antes do resto do app ver
(function converterHeicNosCampos() {
    document.addEventListener('change', async e => {
        const inp = e.target;
        if (!inp || inp.tagName !== 'INPUT' || inp.type !== 'file' || inp.dataset.heicOk === '1' || !inp.files || !inp.files.length) return;
        const lista = [...inp.files];
        let precisa = false;
        for (const f of lista) { if (await ehHeic(f) && !(await navegadorAbre(f))) { precisa = true; break; } }
        if (!precisa) return;
        e.stopImmediatePropagation();
        const novos = [];
        for (const f of lista) { const ok = await fotoLegivel(f); if (ok) novos.push(ok); }
        try {
            const dt = new DataTransfer(); novos.forEach(f => dt.items.add(f));
            inp.files = dt.files;
        } catch (_) { return; }
        if (!novos.length) { inp.value = ''; return; }
        inp.dataset.heicOk = '1';
        inp.dispatchEvent(new Event('change', { bubbles: true }));
        setTimeout(() => { delete inp.dataset.heicOk; }, 0);
    }, true);
})();

function compressImage(file, maxSide = 1200, quality = 0.8) {
    return new Promise((resolve) => {
        if (!file || !file.type || !file.type.startsWith('image/')) return resolve(file);
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
            URL.revokeObjectURL(url);
            let { width, height } = img;
            const maior = Math.max(width, height);
            if (maior > maxSide) {
                const f = maxSide / maior;
                width = Math.round(width * f);
                height = Math.round(height * f);
            }
            const canvas = document.createElement('canvas');
            canvas.width = width; canvas.height = height;
            canvas.getContext('2d').drawImage(img, 0, 0, width, height);
            const universal = ['image/jpeg', 'image/png', 'image/webp'].includes(file.type);
            canvas.toBlob(blob => resolve(blob && (!universal || blob.size < file.size) ? blob : file), 'image/jpeg', quality);
        };
        img.onerror = () => { URL.revokeObjectURL(url); resolve(file); };
        img.src = url;
    });
}

async function uploadImage(bucket, file, opts = {}) {
    let blob = await compressImage(file, opts.maxSide || 1200, opts.quality || 0.8);
    // última garantia: nunca sobe HEIC (o Android e o computador não abrem)
    if (blob === file && await ehHeic(file)) {
        const jpg = await heicParaJpg(file, true).catch(() => null);
        if (!jpg) throw new Error('Não consegui converter essa foto (HEIC). Tente outra foto.');
        blob = await compressImage(jpg, opts.maxSide || 1200, opts.quality || 0.8);
    }
    const ext = (blob.type === 'image/jpeg' || blob !== file) ? 'jpg' : (file.name.split('.').pop() || 'jpg');
    const path = opts.fixedName
        ? `${state.session.user.id}/${opts.fixedName}.${ext}`
        : `${state.session.user.id}/${Date.now()}.${ext}`;
    if (opts.fixedName) await sb.storage.from(bucket).remove([path]);
    const { error } = await sb.storage.from(bucket).upload(path, blob, { upsert: !!opts.fixedName, contentType: blob.type || 'image/jpeg' });
    if (error) throw error;
    return sb.storage.from(bucket).getPublicUrl(path).data.publicUrl;
}

// ---- Fotos privadas (balança e registros "Só eu") ficam em pasta PRIVADA ----
// No banco a foto aparece como "privado:<caminho>". O app troca por um link temporário na hora de mostrar.
const BUCKET_PRIVADO = 'private-images';
const ehPrivada = url => typeof url === 'string' && url.startsWith('privado:');
async function uploadImagemPrivada(file) {
    const blob = await compressImage(file, 1200, 0.8);
    const path = `${state.session.user.id}/${Date.now()}.jpg`;
    const { error } = await sb.storage.from(BUCKET_PRIVADO).upload(path, blob, { contentType: 'image/jpeg' });
    if (error) throw error;
    return 'privado:' + path;
}
const cacheLinksPrivados = {};
async function linkPrivado(ref, validadeSeg = 3600) {
    const path = ref.slice('privado:'.length);
    const c = cacheLinksPrivados[path];
    if (c && c.ate > Date.now() + 60000) return c.url;
    const { data, error } = await sb.storage.from(BUCKET_PRIVADO).createSignedUrl(path, validadeSeg);
    if (data && data.signedUrl) cacheLinksPrivados[path] = { url: data.signedUrl, ate: Date.now() + validadeSeg * 1000 };
    else if (!linkPrivado.avisou) { linkPrivado.avisou = true; try { evento('foto_privada_falhou', { erro: String((error && (error.message || error.error)) || 'sem link').slice(0, 120), path: path.slice(0, 60) }); } catch (_) {} }
    return data ? data.signedUrl : '';
}
// Qualquer <img src="privado:..."> que aparecer na tela é resolvida sozinha
(function resolverImagensPrivadas() {
    const pendentes = new Set();
    let agendado = false;
    const processar = () => {
        agendado = false;
        document.querySelectorAll('img[src^="privado:"]').forEach(img => {
            const ref = img.getAttribute('src');
            if (pendentes.has(img)) return;
            pendentes.add(img);
            img.setAttribute('src', 'data:image/gif;base64,R0lGODlhAQABAAAAACw=');
            img.dataset.privado = ref;
            linkPrivado(ref).then(u => { if (u) img.src = u; pendentes.delete(img); });
        });
    };
    new MutationObserver(() => { if (!agendado) { agendado = true; requestAnimationFrame(processar); } })
        .observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['src'] });
})();
// Mudou de "Só eu" pra público/seguidores: a foto sai da pasta privada
async function tornarFotoPublica(postId) {
    const { data: p } = await sb.from('posts').select('image_url').eq('id', postId).maybeSingle();
    if (!p || !ehPrivada(p.image_url)) return;
    const path = p.image_url.slice('privado:'.length);
    const { data: blob, error } = await sb.storage.from(BUCKET_PRIVADO).download(path);
    if (error || !blob) throw error || new Error('download');
    const novoPath = `${state.session.user.id}/${Date.now()}.jpg`;
    const up = await sb.storage.from('post-images').upload(novoPath, blob, { contentType: 'image/jpeg' });
    if (up.error) throw up.error;
    const url = sb.storage.from('post-images').getPublicUrl(novoPath).data.publicUrl;
    await sb.from('posts').update({ image_url: url }).eq('id', postId);
    await sb.storage.from(BUCKET_PRIVADO).remove([path]);
    document.querySelectorAll(`.post[data-post-id="${postId}"] img.post-photo`).forEach(i => { i.src = url; });
}
// Miniatura leve pra grade do perfil (a foto grande só carrega ao abrir)
async function uploadMiniatura(file) {
    try {
        const blob = await compressImage(file, 420, 0.72);
        const path = `${state.session.user.id}/${Date.now()}_t.jpg`;
        const { error } = await sb.storage.from('post-images').upload(path, blob, { contentType: 'image/jpeg' });
        if (error) return null;
        return sb.storage.from('post-images').getPublicUrl(path).data.publicUrl;
    } catch (_) { return null; }
}

// Apaga do storage a imagem de um post que foi removido
async function removeStoredImage(url) {
    if (!url) return;
    if (ehPrivada(url)) {
        try { await sb.storage.from(BUCKET_PRIVADO).remove([url.slice('privado:'.length)]); } catch (e) {}
        return;
    }
    const marcador = '/post-images/';
    const i = url.indexOf(marcador);
    if (i === -1) return;
    const path = decodeURIComponent(url.slice(i + marcador.length).split('?')[0]);
    try { await sb.storage.from('post-images').remove([path]); } catch (e) {}
}

