// quem está na zona de subir e de cair (com todo mundo em 0, ninguém; empatado com quem está fora da zona, também não cai)
function ligaZonas(d) {
    const lista = d.membros || [], n = lista.length, sobe = new Set(), cai = new Set();
    if (!lista.some(x => Number(x.pts) > 0)) return { sobe, cai };
    // só sobe se a liga de cima estiver aberta nessa semana; só cai se existir liga embaixo
    if (d.nivel < Math.min(4, d.niveis_abertos || 4)) lista.slice(0, d.sobem || 0).forEach(x => { if (Number(x.pts) > 0) sobe.add(x.id); });
    if (d.caem && d.nivel > 1) {
        const limite = lista[n - d.caem - 1];
        lista.slice(n - d.caem).forEach(x => { if (!limite || Number(x.pts) < Number(limite.pts)) cai.add(x.id); });
    }
    return { sobe, cai };
}
// domingo: resultado da semana que fechou (aparece uma vez)
async function talvezResultadoLiga() {
    if (!state.session || document.getElementById('onbTela')) return;
    const d = await carregarLiga(true);
    const a = d && d.anterior; if (!a) return;
    if (document.querySelector('.sheet.on, .x1-tela, .sc.on, .story-viewer.on')) { setTimeout(talvezResultadoLiga, 20000); return; }
    const novo = a.resultado === 'subiu' ? a.nivel + 1 : a.resultado === 'caiu' ? a.nivel - 1 : a.nivel;
    const nv = LIGA_NIVEIS[novo] || LIGA_NIVEIS[1], antes = LIGA_NIVEIS[a.nivel] || LIGA_NIVEIS[1];
    const titulo = a.resultado === 'subiu' ? `Você subiu pra Liga ${nv.nome}!` : a.resultado === 'caiu' ? `Semana nova na Liga ${nv.nome}` : `Você continua na Liga ${nv.nome}`;
    const sub = a.resultado === 'subiu' ? `Terminou em ${a.pos}º na Liga ${antes.nome} com ${a.pts} pts. Liga nova, rivais novos: mostra o que trouxe da ${antes.nome}! 💪`
        : a.resultado === 'caiu' ? `Semana passada foi mais puxada (${a.pts} pts). Semana nova, bora voltar pra ${antes.nome}!`
        : `Terminou em ${a.pos}º com ${a.pts} pts. Essa semana é a vez de subir!`;
    const t = x1Tela('ligaRes', `<div class="lg-res" style="--c:${nv.c}"><span class="liga-med enorme" style="--a:${nv.a};--b:${nv.b}">${nv.emo}</span>
        <b>${titulo}</b><p>${escapeHTML(sub)}</p><button class="bt-min lg-res-bt" data-lg="ver">Ver minha liga</button><button class="lg-res-x" data-lg="ok">Fechar</button></div>`);
    sb.rpc('liga_visto').then(() => {}, () => {});
    if (state.liga && state.liga.d) state.liga.d.anterior = null;
    if (a.resultado === 'subiu') vibrar([20, 40, 20, 40, 80]);
    t.addEventListener('click', e => {
        const b = e.target.closest('[data-lg]'); if (!b) return;
        x1FecharTela('ligaRes');
        if (b.dataset.lg === 'ver') setTimeout(abrirLiga, 200);
    });
}

// ---- Saúde dos desafios: quem registrou algo nos últimos 3 dias (pra ver desafio esfriando antes de morrer) ----
async function hydrateSaudeDesafios() {
    const box = document.getElementById('admSaude'); if (!box) return;
    const { data, error } = await sb.rpc('admin_saude_desafios');
    if (!document.getElementById('admSaude')) return;
    if (error) { box.innerHTML = `<div class="chart-card"><p class="faixa-nota" style="margin:0">Não consegui carregar: ${escapeHTML(error.message)}. Rode a seção 32 do SQL.</p></div>`; return; }
    const lista = data || [];
    if (!lista.length) { box.innerHTML = `<div class="chart-card"><p class="faixa-nota" style="margin:0">Nenhum desafio rolando agora.</p></div>`; return; }
    box.innerHTML = lista.map(c => {
        const pct = Number(c.pct) || 0, cor = pct >= 60 ? 'bom' : pct >= 30 ? 'medio' : 'ruim';
        const dif = (c.ativos || 0) - (c.ativos_antes || 0);
        const tend = dif > 0 ? `<span class="sd-tend sobe">↑ ${dif} a mais que nos 3 dias antes</span>` : dif < 0 ? `<span class="sd-tend cai">↓ ${-dif} a menos que nos 3 dias antes</span>` : `<span class="sd-tend">igual aos 3 dias antes</span>`;
        const sumidos = (c.sumidos || []);
        return `<div class="chart-card sd-card ${cor}">
            <div class="sd-topo"><div><b>${escapeHTML(c.nome || 'Desafio')}</b><small>dia ${Math.min(c.dia, c.de)} de ${c.de}</small></div><span class="sd-pct">${pct}%</span></div>
            <div class="sd-barra"><i style="width:${Math.max(2, pct)}%"></i></div>
            <p class="sd-txt"><b>${c.ativos || 0} de ${c.membros || 0}</b> registraram algo nos últimos 3 dias</p>
            ${tend}
            ${sumidos.length ? `<div class="sd-sumidos"><small>Sumidos:</small>${sumidos.map(u => `<button type="button" class="sd-pessoa" data-act="view-user" data-uid="${u.id}">${escapeHTML(u.nome || '?')}${u.dias != null ? ` <i>${u.dias}d</i>` : ' <i>nunca</i>'}</button>`).join('')}</div>` : ''}
        </div>`;
    }).join('') + '<p class="faixa-nota" style="margin-top:0">Verde: 60% ou mais ativos. Amarelo: de 30% a 59%. Vermelho: menos de 30%. Os que estão no vermelho aparecem primeiro.</p>';
}

// ---- Onde as pessoas desistem: funis montados com os eventos de uso ----
const NOME_PASSO_ONB = { objetivo: 'Objetivo', treino: 'O que curte', pessoas: 'Pessoas' };
const NOME_KIND = { workout: 'Treino', meal: 'Refeição', water: 'Água', sleep: 'Sono', post: 'Post', story: 'Story', weight: 'Peso', '?': 'Sem tipo' };
async function hydrateAdminFunil() {
    const box = document.getElementById('admFunil'); if (!box) return;
    box.innerHTML = '<div class="spinner"></div>';
    const dias = state.funilDias || 7;
    const { data: f, error } = await sb.rpc('admin_funil', { p_dias: dias });
    if (!document.getElementById('admFunil')) return;
    if (error || !f) { box.innerHTML = `<div class="chart-card"><p class="faixa-nota" style="margin:0">Não consegui carregar${error ? ': ' + escapeHTML(error.message) : ''}. Rode a seção 31 do SQL.</p></div>`; return; }
    if (!f.eventos) { box.innerHTML = `<div class="chart-card"><p class="faixa-nota" style="margin:0">Ainda sem dados nesses ${dias} dias. Os números aparecem conforme a galera usa o app novo.</p></div>`; return; }
    const pct = (a, b) => b ? Math.round(a / b * 100) : 0;
    // barra de funil: cada etapa em relação à primeira
    const funil = (titulo, etapas, nota = '') => {
        const base = Math.max(1, etapas[0] ? etapas[0][1] : 1);
        return `<div class="chart-card fn-card"><b class="fn-t">${titulo}</b>
            ${etapas.map(([nome, n, alerta], k) => {
                const p = pct(n, base), caiu = k ? pct((etapas[k - 1][1] || 0) - n, etapas[k - 1][1] || 0) : 0;
                return `<div class="fn-linha${alerta ? ' alerta' : ''}"><span class="fn-nome">${escapeHTML(nome)}</span><span class="fn-barra"><i style="width:${Math.max(2, p)}%"></i></span><span class="fn-n">${n}${k ? `<small>${p}%</small>` : ''}</span></div>${k && caiu >= 30 ? `<div class="fn-queda">${caiu}% pararam antes daqui</div>` : ''}`;
            }).join('')}
            ${nota ? `<p class="faixa-nota" style="margin-bottom:0">${nota}</p>` : ''}</div>`;
    };
    let html = `<div class="stat-grid fn-topo">
        <div class="stat-card"><div class="num">${f.pessoas || 0}</div><div class="lbl">Pessoas</div></div>
        <div class="stat-card"><div class="num">${f.aberturas || 0}</div><div class="lbl">Aberturas</div></div>
    </div>`;
    const onb = f.onboarding || [];
    if (onb.length) {
        const ult = onb[onb.length - 1];
        const etapas = onb.map(x => [`${x.i}. ${NOME_PASSO_ONB[x.passo] || x.passo}`, x.viram]);
        etapas.push(['Terminou', onb.reduce((t, x) => t + (x.terminaram || 0), 0)]);
        const pulos = onb.filter(x => x.pularam).map(x => `${x.pularam} no passo ${x.i}`).join(', ');
        html += funil('Primeiro acesso', etapas, pulos ? `Tocaram em "Pular": ${pulos}.` : (ult ? '' : ''));
    }
    (f.registrar || []).forEach(r => {
        html += funil(`Registrar ${(NOME_KIND[r.kind] || r.kind).toLowerCase()}`, [['Abriu', r.abriu], ['Salvou', r.salvou]],
            r.desistiu ? `${r.desistiu} ${r.desistiu === 1 ? 'vez fechou' : 'vezes fecharam'} sem salvar${r.seg_desistiu != null ? `, em média depois de ${r.seg_desistiu}s` : ''}.` : '');
    });
    const st = f.story || {};
    if (st.abriu) html += funil('Criar story', [['Abriu', st.abriu], ['Publicou', st.publicou]]);
    const x1 = f.x1 || {};
    if (x1.abriu) html += funil('Chamar pro X1', [['Abriu', x1.abriu], ['Enviou', x1.enviou]]);
    const se = f.semana || {};
    if (se.perguntou) html += funil('"Como é sua semana?" (depois do 1º treino)', [['Perguntou', se.perguntou], ['Montou', se.montou]], se.depois ? `${se.depois} tocaram em "Depois".` : '');
    const ab = f.abertura || [];
    if (ab.length) {
        const linha = (et, cache) => { const x = ab.find(a => a.etapa === et && a.cache === cache); return x ? `${br(x.ms / 1000, 1)}s <small>(${x.vezes}x)</small>` : '-'; };
        html += `<div class="chart-card fn-card"><b class="fn-t">Tempo pra abrir (mediana)</b>
            <div class="fn-tab"><span></span><span>1ª vez</span><span>Com feed salvo</span>
            <span>Perfil</span><b>${linha('perfil', false)}</b><b>${linha('perfil', true)}</b>
            <span>Tela pronta</span><b>${linha('tela', false)}</b><b>${linha('tela', true)}</b></div></div>`;
    }
    const of = f.offline || {};
    if (of.guardados || of.enviados) html += `<div class="chart-card fn-card"><b class="fn-t">Sem internet</b><p class="faixa-txt" style="margin:6px 0 0">${of.guardados || 0} registros guardados no aparelho · ${of.enviados || 0} enviados depois</p></div>`;
    box.innerHTML = html;
}
