    state.chatRespondendo = null;
    state.chatTema = null;
    state.chatLimite = CHAT_JANELA;
    sb.rpc('chat_tema', { cid: conversationId }).then(({ data }) => {
        if (state.chatConversationId !== conversationId || !data) return;
        state.chatTema = data; aplicarTemaChat(data.tema); pintarAvisoTema();
    }, () => {});
    try {
        state.chatMessages = await loadChatMessages(conversationId);
        await carregarExtrasDoChat(conversationId);
    } catch (error) {
        $('#chatMessages').innerHTML = `<p style="color:var(--danger)">Erro: ${error.message}</p>`;
        return;
    }
    paintChatMessages();
    await sb.rpc('mark_conversation_read', { conv_id: conversationId });
    updateUnreadBadge();

    const input = $('#chatInput');
    let ultimoAviso = 0;
    input.addEventListener('input', () => {
        input.style.height = 'auto';
        input.style.height = Math.min(120, input.scrollHeight) + 'px';
        const agora = Date.now();
        if (chatChannel && agora - ultimoAviso > 2000) {
            ultimoAviso = agora;
            try { chatChannel.send({ type: 'broadcast', event: 'typing', payload: { uid: me } }); } catch (_) {}
        }
    });
