                topo = `<div class="cmsg-story"><span class="cmsg-st-mini">${mini}<em>Story indisponível</em></span><span class="cmsg-st-lbl">${mine ? 'Você respondeu ao story' : 'Respondeu ao seu story'}</span></div>`;
