            const quem = ehGrupo && !mine ? (membros[m.sender_id] || {}) : null;
            const nomeG = quem && !comAnt ? `<span class="cmsg-autor" style="color:${corAutor(m.sender_id)}">${escapeHTML(String(quem.nome || '').split(' ')[0] || 'Alguém')}</span>` : '';
