const COR_DEP_ANTIGA = { menta: 'verde', laranja: 'coral', vinho: 'lilas', neutro: 'prata' };
const corDep = cor => CORES_DEP[cor] ? cor : (COR_DEP_ANTIGA[cor] || 'prata');
const estiloCorDep = cor => { const k = CORES_DEP[corDep(cor)]; return `--dc:${k[0]};--dg:${k[1]}`; };
function abrirEscreverDepoimento(uid, nome, editando = null) {
    let cor = corDep((editando && editando.cor) || 'verde');
    const primeiro = escapeHTML(String(nome || '').split(' ')[0]);
    const { f, fechar } = x1Folha(`<h3 class="x1-folha-t">${editando ? 'Editar depoimento' : `Depoimento pra ${primeiro}`}</h3>
        <p class="dep-sub">Ela lê e decide se publica no perfil. Seja gentil e verdadeiro.</p>
        <div class="dep-vidro dep-redigir" id="depCard" style="${estiloCorDep(cor)}"><span class="dep-brilho"></span>
            <textarea id="depTexto" maxlength="140" rows="3" placeholder="O que te inspira em ${primeiro}?">${editando ? escapeHTML(editando.texto) : ''}</textarea>
            <span class="dep-conta"><b id="depConta">${editando ? editando.texto.length : 0}</b>/140</span>
        </div>
        <div class="dep-cores" id="depCores">${Object.entries(CORES_DEP).map(([k, v]) => `<button type="button" class="dep-cor${k === cor ? ' on' : ''}" data-cor="${k}" style="--dg:${v[1]};--dc:${v[0]}" aria-label="${k}"></button>`).join('')}</div>
        <button class="btn x1-btn" id="depEnviar" ${editando ? '' : 'disabled'}>${editando ? 'Salvar' : 'Enviar'}</button>`, 'depSheet');
    const campo = f.querySelector('#depTexto'), enviar = f.querySelector('#depEnviar'), card = f.querySelector('#depCard');
    const ajustar = () => { campo.style.height = 'auto'; campo.style.height = Math.min(160, campo.scrollHeight) + 'px'; };
    campo.addEventListener('input', () => { f.querySelector('#depConta').textContent = campo.value.length; enviar.disabled = !campo.value.trim(); ajustar(); });
    setTimeout(() => { campo.focus(); ajustar(); }, 250);
    f.querySelector('#depCores').addEventListener('click', e => {
        const b = e.target.closest('[data-cor]'); if (!b) return;
        cor = b.dataset.cor; card.setAttribute('style', estiloCorDep(cor));
        f.querySelectorAll('.dep-cor').forEach(x => x.classList.toggle('on', x === b)); vibrar(5);
    });
    enviar.onclick = async () => {
        const texto = campo.value.trim();
        if (textoOfensivo(texto)) { toast('Esse texto tem palavras que não combinam com um depoimento. Que tal reescrever?', 'err'); return; }
        enviar.disabled = true; enviar.textContent = 'Enviando...';
        const { data: novoId, error } = editando
            ? await sb.rpc('editar_depoimento', { did: editando.id, texto })
            : await sb.rpc('enviar_depoimento', { alvo: uid, texto });
        if (error) { toast(msgErro(error), 'err'); enviar.disabled = false; enviar.textContent = editando ? 'Salvar' : 'Enviar'; return; }
        const did = editando ? editando.id : novoId;
        if (did) await sb.rpc('depoimento_cor', { did, p_cor: cor }).then(() => {}, () => {});
        fechar();
        toast(editando ? 'Depoimento atualizado' : 'Depoimento enviado. Agora é com ela!', 'ok');
        const aba = document.querySelector('.ig-tab[data-tab="depoimentos"]');
        if (aba) aba.click();
    };
}

// ---- Pedir depoimento pra um amigo (vocês se seguem) ----
async function abrirPedirDepoimento() {
    const lupa = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"/><path d="M20 20l-4-4"/></svg>';
    const { f } = x1Folha(`<h3 class="x1-folha-t">Pedir um depoimento</h3>
        <p class="dep-sub">Só aparecem amigos (vocês se seguem). A pessoa recebe um aviso e escreve direto no seu perfil.</p>
        <label class="pd-busca">${lupa}<input id="pdBusca" type="search" placeholder="Buscar amigo" autocomplete="off" autocapitalize="off"></label>
        <div class="pd-lista" id="pdLista">${esqueletoAba('depoimentos')}</div>`, 'pedirDepSheet');
    const { data, error } = await sb.rpc('amigos_para_depoimento');
    const box = f.querySelector('#pdLista'); if (!box) return;
    if (error) { box.innerHTML = `<p class="faixa-nota">Não consegui carregar seus amigos agora.</p>`; return; }
    const lista = data || [];
    if (!lista.length) { box.innerHTML = '<p class="pd-vazio">Você ainda não tem amigos que se seguem com você. Quando alguém te seguir de volta, aparece aqui.</p>'; return; }
    const SETE = 7 * 86400000;
    const pintar = termo => {
        const t = String(termo || '').trim().toLowerCase().replace(/^@/, '');
        const filtrada = !t ? lista : lista.filter(u => (u.display_name || '').toLowerCase().includes(t) || (u.username || '').toLowerCase().includes(t));
        box.innerHTML = filtrada.length ? filtrada.map(u => {
            const recente = u.pedido_em && Date.now() - new Date(u.pedido_em).getTime() < SETE;
            const bt = recente ? '<button class="bt-min cinza" disabled>Pedido ✓</button>'
                : `<button class="bt-min" data-pd="${u.id}">${u.ja_deixou ? 'Pedir de novo' : 'Pedir'}</button>`;
            return `<div class="pd-item">${avatarHTML(u, 'sm')}<div class="pd-nome"><b>${escapeHTML(u.display_name || u.username || '')}</b><small>${u.ja_deixou ? 'Já deixou um depoimento' : '@' + escapeHTML(u.username || '')}</small></div>${bt}</div>`;
        }).join('') : '<p class="pd-vazio">Ninguém com esse nome entre seus amigos.</p>';
    };
    pintar('');
    f.querySelector('#pdBusca').addEventListener('input', e => pintar(e.target.value));
    box.addEventListener('click', async e => {
        const b = e.target.closest('[data-pd]'); if (!b) return;
        b.disabled = true;
        const { error: er } = await sb.rpc('pedir_depoimento', { alvo: b.dataset.pd });
        if (er) { toast(msgErro(er), 'err'); b.disabled = false; return; }
        const u = lista.find(x => x.id === b.dataset.pd); if (u) u.pedido_em = new Date().toISOString();
        b.outerHTML = '<button class="bt-min cinza" disabled>Pedido ✓</button>';
        vibrar(8);
        toast('Pedido enviado ✍️', 'ok');
    });
}
