(function gestosDoStory() {
    const v = document.getElementById('storyViewer');
    let x0 = 0, y0 = 0, t0 = 0, puxando = false, ativo = false, lateral = false;
    const livre = t => t.closest('input, textarea, button, .sv-menu, #svMenu, .sheet, .sv-enq');
    const palco = () => v.querySelector('.story-content');
    v.addEventListener('touchstart', e => {
        ativo = e.touches.length === 1 && !livre(e.target);
        x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; t0 = Date.now(); puxando = false; lateral = false;
        state.storyArrastou = false;
    }, { passive: true });
    v.addEventListener('touchmove', e => {
        if (!ativo) return;
        const dx = e.touches[0].clientX - x0, dy = e.touches[0].clientY - y0;
        if (!puxando) {
            if (dy > 12 && dy > Math.abs(dx) * 1.3) {
                puxando = true; state.storyArrastou = true;
                v.classList.add('puxando');
                if (!v.classList.contains('paused')) pausarStoryNoPonto();
            } else return;
        }
        const d = Math.max(0, dy);
        v.style.transform = `translateY(${d}px) scale(${1 - Math.min(0.2, d / 1600)})`;
        v.style.borderRadius = Math.min(28, d / 6) + 'px';
        v.style.opacity = String(Math.max(0.35, 1 - d / 700));
    }, { passive: true });
    v.addEventListener('touchend', e => {
        if (!ativo) return;
        const dx = e.changedTouches[0].clientX - x0, dy = e.changedTouches[0].clientY - y0;
        if (!puxando) {
            if (dy < -60 && Math.abs(dy) > Math.abs(dx) * 1.5 && state.storyAtual) { state.storyArrastou = true; abrirQuemViuStory(); }
            return;
        }
        puxando = false;
        const rapido = dy / Math.max(1, Date.now() - t0) > 0.6;
        v.classList.remove('puxando');
        v.classList.add('soltando');
        if (dy > window.innerHeight * 0.22 || (rapido && dy > 40)) {
            v.style.transform = `translateY(${window.innerHeight}px) scale(.8)`;
            v.style.opacity = '0';
            setTimeout(() => {
                closeStoryViewer();
                v.classList.remove('soltando');
                v.style.transform = ''; v.style.opacity = ''; v.style.borderRadius = '';
            }, 220);
        } else {
            v.style.transform = ''; v.style.opacity = ''; v.style.borderRadius = '';
            setTimeout(() => { v.classList.remove('soltando'); retomarStoryDoPonto(); }, 220);
        }
    });
})();

function advanceStory(dir) {
    clearTimeout(state.storyTimer);
    if ($('#storyViewer').classList.contains('paused')) return;
    const group = state.storiesData[state.storyIdx];
    if (!group) { closeStoryViewer(); return; }
    if (dir > 0) {
        state.storyItemIdx++;
        if (state.storyItemIdx >= group.items.length) {
            state.storyIdx++;
            state.storyItemIdx = primeiroNaoVisto(state.storiesData[state.storyIdx]);
            if (state.storyIdx >= state.storiesData.length) { closeStoryViewer(); return; }
        }
    } else {
        state.storyItemIdx--;
        if (state.storyItemIdx < 0) {
            state.storyIdx--;
            if (state.storyIdx < 0) { state.storyIdx = 0; state.storyItemIdx = 0; }
            else state.storyItemIdx = state.storiesData[state.storyIdx].items.length - 1;
        }
    }
    showCurrentStory();
}

