    if (state.composerKind === 'workout' && !state.wEscolhido) { toast('Escolha o que você treinou', 'err'); const c = document.getElementById('wTypeChips'); if (c) c.classList.add('pede'), setTimeout(() => c.classList.remove('pede'), 900); return; }
