// INIT
// ============================================================
// quem chegou pelo link de convite e ainda não tem conta: mostra quem chamou e abre direto o cadastro
async function mostrarEntradaConvite() {
    try {
        const quem = localStorage.getItem('pulso-link-user'), tipo = localStorage.getItem('pulso-link-tipo');
        if (!quem || tipo !== 'convite' || document.getElementById('cvEntrada')) return;
        const { data } = await sb.rpc('convite_perfil', { u: quem });
        const p = data && (Array.isArray(data) ? data[0] : data);
        if (!p) return;
        const nome = String(p.display_name || p.username || '').split(' ')[0];
        const tabs = document.getElementById('authTabs'); if (!tabs) return;
        tabs.insertAdjacentHTML('beforebegin', `<div class="cv-entrada" id="cvEntrada">${p.avatar_url ? `<img src="${escapeHTML(p.avatar_url)}" alt="">` : avatarHTML({ id: p.username, display_name: p.display_name }, 'md')}
            <span><b>${escapeHTML(nome)} te chamou pra treinar junto</b><small>Fazendo o 1º treino, você e ${escapeHTML(nome)} ganham 10 pontos 🎁</small></span></div>`);
        showAuthScreen('signup');
    } catch (_) {}
}
async function boot() {
    if (boot.rodando) return;
    boot.rodando = true;
    try { await bootInterno(); } finally { boot.rodando = false; }
}
async function bootInterno() {
    try {
        const q = new URLSearchParams(location.search);
        const u = q.get('u') || q.get('seguir');
        if (q.get('d')) localStorage.setItem('pulso-link-desafio', q.get('d'));
        if (q.get('abrir')) state.abrirPush = { tela: q.get('abrir'), id: q.get('id') || '', x1: q.get('x1') || '' };
        if (u) {
            localStorage.setItem('pulso-link-user', u);
            localStorage.setItem('pulso-link-tipo', q.get('u') ? 'perfil' : 'convite');
        }
    } catch (_) {}
    // Detecta se veio pelo link de "esqueci senha" (URL tem #access_token e type=recovery)
    const hash = window.location.hash || '';
    const isRecovery = hash.includes('type=recovery');

    const { data: { session } } = await sb.auth.getSession();

    if (isRecovery && session) {
        // Chegou pelo link do email - mostra tela de nova senha
        $('#authScreen').style.display = 'flex';
        $('#app').classList.remove('on');
        showAuthScreen('reset-password');
        // Limpa a URL pra não mostrar o hash na barra
        history.replaceState(null, '', window.location.pathname);
        return;
    }

    if (!session) {
        $('#authScreen').style.display = 'flex';
        $('#app').classList.remove('on');
        mostrarEntradaConvite();
        return;
    }
    state.session = session;

    // carrega ou cria profile. Pra abrir rápido: se já tem uma cópia salva do perfil, entra com ela
    // e atualiza por trás. Seguidores e pontos vão em paralelo, sem esperar um pelo outro.
    const uidBoot = session.user.id;
    const chaveProf = 'pulso-prof-' + uidBoot;
    let profCache = null;
    try { profCache = JSON.parse(lsGet(chaveProf) || 'null'); } catch (_) {}
    if (profCache && profCache.id !== uidBoot) profCache = null;
    const profP = (async () => {
        let { data: prof, error } = await sb.from('profiles').select('*').eq('id', uidBoot).maybeSingle();
        if (error) return null;
        if (!prof) {
            const meta = session.user.user_metadata || {};
            const insert = await sb.from('profiles').insert({
                id: uidBoot,
                username: (meta.username || `user_${uidBoot.slice(0,8)}`).toLowerCase(),
                display_name: meta.display_name || 'Novo usuário'
            }).select().single();
            prof = insert.data;
        }
        if (prof) { try { localStorage.setItem(chaveProf, JSON.stringify(prof)); } catch (_) {} }
        return prof;
    })().catch(() => null);
    const segP = Promise.resolve().then(() => sb.rpc('my_followers_count')).then(r => r && r.data).catch(() => null);
    const cacheServe = profCache && (profCache.is_admin || !profCache.access_status || profCache.access_status === 'aprovado');
    let prof = cacheServe ? profCache : await profP;
    if (!prof) prof = profCache || await profP;
    state.profile = prof;
    marcarTempo('perfil');

    // Cadastro esperando liberação do administrador
    if (prof && prof.access_status && prof.access_status !== 'aprovado' && !prof.is_admin) {
        mostrarTelaAguardandoAcesso(prof.access_status);
        return;
    }
    const espera = document.getElementById('telaEspera');
    if (espera) espera.remove();

    $('#authScreen').style.display = 'none';
    $('#app').classList.add('on');

    // Ajusta privacidade padrão: se 0 seguidores, público; senão, seguidores
    const chaveSeg = 'pulso-seg-' + uidBoot;
    const aplicarSeg = n => {
        state.defaultPrivacy = (Number(n) || 0) > 0 ? 'followers' : 'public';
        state.composerPrivacy = state.defaultPrivacy;
        updatePrivacyChip();
    };
    const segCache = lsGet(chaveSeg);
    if (segCache != null) {
        aplicarSeg(segCache);
        segP.then(n => { if (n != null) { lsSet(chaveSeg, String(n)); if (!state.composerAberto) aplicarSeg(n); } });
    } else {
        const n = await segP; if (n != null) lsSet(chaveSeg, String(n)); aplicarSeg(n);
    }

    loadScore();
    carregarOficial();
    // Veio de uma notificação? Vai direto pro lugar. Senão, abre na aba mais usada.
    const ap = state.abrirPush; state.abrirPush = null;
    if (ap && ap.tela === 'desafio' && ap.x1) { await switchView('desafio'); abrirX1(ap.x1); }
    else if (ap && ap.tela === 'post' && ap.id) { await switchView('feed'); openPostSheet(ap.id); }
    else if (ap && ap.tela === 'desafio' && ap.id) await switchView('challenge', { id: ap.id });
    else if (ap && ap.tela === 'perfil' && ap.id) await switchView('user-profile', { uid: ap.id });
    else if (ap && ap.tela === 'depoimento' && ap.id) await abrirPedidoDepoimento(ap.id, '');
    else if (ap && ap.tela === 'parabens' && ap.id) { await switchView('feed'); abrirParabens(ap.id); }
    else if (ap && ap.tela === 'postsemana') {
        // aviso de domingo: abre direto a escolha do modelo da semana que acabou
        await switchView('feed');
        const ini = janelaDoResumo() ? semanaDoResumo() : new Date(inicioDaSemana(new Date()).getTime() - 7 * 86400000);
        evento('resumo_push_abriu', {});
        setTimeout(() => abrirModelosSemana(ini), 450);
    }
    else if (ap && ['notifications', 'messages', 'progress', 'coach'].includes(ap.tela)) await switchView(ap.tela);
    else await switchView(abaInicial());
    marcarTempo('tela');
    // perfil fresquinho do servidor (se entrou com a cópia salva)
    if (prof === profCache) {
        const fresco = await profP;
        if (fresco) {
            state.profile = fresco;
            if (fresco.access_status && fresco.access_status !== 'aprovado' && !fresco.is_admin) { mostrarTelaAguardandoAcesso(fresco.access_status); return; }
        }
    }
    if (ap && ap.tela === 'treino' && trGet()) setTimeout(() => abrirTreinoVivo(), 300);
    if (ap && ap.tela === 'semana') setTimeout(() => abrirSemana(), 400);
    if (ap && ap.tela === 'treinar' && ap.id) setTimeout(() => abrirModoTreino({ a: 'Musculação', g: [ap.id] }), 400);
    if (ap && ap.tela === 'agua') setTimeout(() => { limparComposer(); setComposerKind('water'); abrirComposer(); }, 350);
    state.bootPronto = true;
    evento('app_abriu', { instalado: !!(window.matchMedia && matchMedia('(display-mode: standalone)').matches), offline: !navigator.onLine });
    updateUnreadBadge();
    updateNotifBadge();
    if (!contaOficial()) checarConquistas(true);
    checarConvite();
    enviarFilaOffline(); setTimeout(() => enviarFilaChat(), 3000);
    setTimeout(enviarRascunhos, 2500);

    await carregarBlocked();
    carregarSalvos();
    setTimeout(enviarFilaOffline, 3000);
    setTimeout(atualizarBadgeDesafio, 2500);
    if (!contaOficial()) { setTimeout(checarConvitesX1, 3000); setTimeout(pintarPilulaTreino, 1500); }
    if (!contaOficial()) setTimeout(() => { const vai = () => prepararInsight(); if (window.requestIdleCallback) requestIdleCallback(vai, { timeout: 5000 }); else vai(); }, 12000);
    if (!contaOficial()) setTimeout(() => { const vai = () => talvezPerguntarPausa(); if (window.requestIdleCallback) requestIdleCallback(vai, { timeout: 5000 }); else vai(); }, 4500);
    if (!contaOficial()) setTimeout(() => { const vai = () => talvezResultadoLiga(); if (window.requestIdleCallback) requestIdleCallback(vai, { timeout: 5000 }); else vai(); }, 7000);
    // o coach já começa a montar o dia por trás (quando a pessoa chegar na Evolução, está pronto)
    if (!contaOficial()) setTimeout(() => { const vai = () => { try { prepararCoach(); } catch (_) {} }; if (window.requestIdleCallback) requestIdleCallback(vai, { timeout: 4000 }); else vai(); }, 9000);
    setTimeout(registrarAcesso, 2000);
    if (!contaOficial()) setTimeout(checarConquistasNovas, 6000);
    if (!contaOficial()) { setTimeout(checarQuedaCoach, 8000); setTimeout(carregarCopoAgua, 5000); }
    setTimeout(converterFotosHeic, 20000);
    setTimeout(converterMeuAvatarHeic, 8000);
    setTimeout(tentarAnalisesPendentes, 12000);
    setTimeout(manterPushAtivo, 4000);
    setTimeout(limparStoriesAntigos, 15000);
    // anuncia desafios que acabaram (uma vez só, pra todos os participantes)
    setTimeout(() => sb.rpc('anunciar_fim_desafios').then(() => updateNotifBadge && updateNotifBadge()), 3500);
    if (contaOficial()) {}  // conta oficial do Pulso: sem primeiros passos, metas e lembretes
    else if (state.profile && state.profile.onboarding_done === false) setTimeout(() => abrirPrimeirosPassos(0), 900);
    else {
        setTimeout(() => convidarParaInstalar(false), 9000);
    }
    if (!contaOficial()) { checkDailyReminder(); setTimeout(checarRevisaoObjetivo, 2500); }

    // Aceite dos termos (uma vez por pessoa)
    if (!state.profile.terms_accepted_at || state.profile.terms_version !== TERMOS_VERSAO) {
        setTimeout(openTermsSheet, 300);
    }

    // Primeiro acesso: pede os dados que alimentam evolução e coach
    if (!contaOficial() && !state.profile.altura && !state.profile.peso_inicial) {
        setTimeout(openOnboarding, 600);
    }

    // Credita perda de peso que ainda não virou ponto (ex.: pesagens antigas)
    if (!contaOficial()) sb.rpc('credit_weight_loss').then(({ data }) => {
        const p = Number((data && data[0] && data[0].pts) || 0);
        if (p > 0) { toast(`+${p} pontos pela sua perda de peso até aqui 🎉`, 'ok'); loadScore(); }
    });
}

sb.auth.onAuthStateChange((event, session) => {
    if (event === 'PASSWORD_RECOVERY') {
        // Usuário clicou no link de recuperação - mostra tela de nova senha
        state.session = session;
        $('#authScreen').style.display = 'flex';
        $('#app').classList.remove('on');
        showAuthScreen('reset-password');
        return;
    }
    if (event === 'SIGNED_IN' || event === 'INITIAL_SESSION') {
        if (session && !state.session) boot();
    } else if (event === 'SIGNED_OUT') {
        location.reload();
    }
});

boot();

