// "10-12" → 10 · "15/12/10" → 15 · "30s" → 30 · "até a falha" → null
const repsNum = r => { const x = String(r == null ? '' : r).match(/\d+/); return x ? Math.max(1, Math.min(60, parseInt(x[0]))) : null; };
